import { ChangeDetectionStrategy, Component, effect, Input } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';

import { BlogPost } from '../../../../providers/blog/wordpress-post.model';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { TranslationService } from '../../../../core/services/translation.service';

const TITLE_MAX_LENGTH = 60;
const DESCRIPTION_MAX_LENGTH = 220;

@Component({
	selector: 'app-blog-card',
	standalone: true,
	imports: [CommonModule, DatePipe, TranslateModule],
	templateUrl: './blog-card.component.html',
	styleUrl: './blog-card.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BlogCardComponent {
	@Input({ required: true }) post!: BlogPost;

	get displayTitle(): string {
		const title = this.post.title;
		return title.length > TITLE_MAX_LENGTH
			? `${title.slice(0, TITLE_MAX_LENGTH).trimEnd()}...`
			: title;
	}
	get displayDescription(): string {
		const description = this.post.excerpt;
		return description.length > DESCRIPTION_MAX_LENGTH
			? `${description.slice(0, DESCRIPTION_MAX_LENGTH).trimEnd()}...`
			: description;
	}

	cursorX = 0;
	cursorY = 0;
	isCursorActive = false;
	constructor(
		public translationService: TranslationService,
		private translate: TranslateService,
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}
	showCursor(event: MouseEvent): void {
		this.isCursorActive = true;
		this.moveCursor(event);
	}

	hideCursor(): void {
		this.isCursorActive = false;
	}

	moveCursor(event: MouseEvent): void {
		const target = event.currentTarget as HTMLElement;
		const rect = target.getBoundingClientRect();

		this.cursorX = event.clientX - rect.left;
		this.cursorY = event.clientY - rect.top;
	}
}
