import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit, PLATFORM_ID, effect } from '@angular/core';
import { CommonModule, DOCUMENT, isPlatformBrowser } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';
import { ClientsService } from '../../../providers/clients/clients.service';
import { environment } from '../../../../environments/environment';

@Component({
	selector: 'app-logos',
	standalone: true,
	imports: [CommonModule, TranslateModule],
	templateUrl: './logos.component.html',
	styleUrl: './logos.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LogosComponent implements OnInit {

	baseUrl: any;
	logos: any[] = [];

	constructor(
		@Inject(DOCUMENT) private document: Document,
		@Inject(PLATFORM_ID) private platformId: Object,
		public translationService: TranslationService,
		private clientsService: ClientsService,
		private cdr: ChangeDetectorRef,
	) {
		this.baseUrl = environment.baseUrl;
		effect(() => {
			const locale = this.translationService.currentLang() === 'ar' ? 'ar' : 'en';
		});
	}

	ngOnInit(): void {
		this.getAllLogos();
	}

	getAllLogos() {
		this.clientsService.getClients({}).subscribe({
			next: (response: any) => {
				const clients = response.body.result;
				this.logos = clients.map((item: any, index: number) => ({
					id: item._id || index,
					src: `${this.baseUrl}/public/logo/${item.media_image_data.src}`,
					alt: item.media_image_data.alt,
					title: item.media_image_data.name,
				}));
				this.cdr.detectChanges();
			},
			error: (err) => console.log(err)
		});
	}

	get logoTracks(): any[][] {
		const tracks: any[][] = [[], [], []];

		this.logos.forEach((logo, index) => {
			tracks[index % 3].push(logo);
		});

		return tracks;
	}
}