import { Inject, Injectable, PLATFORM_ID, TransferState, makeStateKey } from '@angular/core';
import { isPlatformBrowser, isPlatformServer } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { catchError, map, shareReplay, tap } from 'rxjs/operators';

import { environment } from '../../../environments/environment';
import { BlogPost, WordpressPost } from './wordpress-post.model';

@Injectable({
	providedIn: 'root'
})
export class BlogService {
	private readonly endpoint = `${environment.wordpressApiUrl}/posts`;
	private readonly latestPostsByKey = new Map<string, Observable<BlogPost[]>>();

	constructor(
		private readonly http: HttpClient,
		private readonly transferState: TransferState,
		@Inject(PLATFORM_ID) private readonly platformId: Object
	) { }

	// Cached per lang+limit so every <app-blog /> instance requesting the same
	// combination shares one HTTP request, and TransferState carries the server's
	// response into the browser so hydration doesn't re-fetch it.
	getLatestPosts(limit = 3, lang: string = 'en'): Observable<BlogPost[]> {
		const cacheKey = `${lang}:${limit}`;
		const cached$ = this.latestPostsByKey.get(cacheKey);
		if (cached$) {
			return cached$;
		}

		const stateKey = makeStateKey<BlogPost[]>(`wordpress-latest-posts:${cacheKey}`);

		if (isPlatformBrowser(this.platformId) && this.transferState.hasKey(stateKey)) {
			const cachedPosts = this.transferState.get(stateKey, []);
			this.transferState.remove(stateKey);
			const posts$ = of(cachedPosts).pipe(shareReplay({ bufferSize: 1, refCount: false }));
			this.latestPostsByKey.set(cacheKey, posts$);
			return posts$;
		}

		const params = {
			per_page: String(limit),
			orderby: 'date',
			order: 'desc',
			_embed: 'true',
			status: 'publish',
			lang
		};

		const posts$ = this.http.get<WordpressPost[]>(this.endpoint, { params }).pipe(
			map((posts) => posts.map((post) => this.toBlogPost(post))),
			tap((posts) => {
				if (isPlatformServer(this.platformId)) {
					this.transferState.set(stateKey, posts);
				}
			}),
			catchError((error) => {
				console.warn('BlogService: failed to load latest WordPress posts', error?.message ?? error);
				return of([]);
			}),
			shareReplay({ bufferSize: 1, refCount: false })
		);

		this.latestPostsByKey.set(cacheKey, posts$);
		return posts$;
	}

	private toBlogPost(post: WordpressPost): BlogPost {
		const featuredMedia = post._embedded?.['wp:featuredmedia']?.[0];
		const category = post._embedded?.['wp:term']?.[0]?.[0]?.name ?? '';

		return {
			id: post.id,
			date: post.date,
			slug: post.slug,
			link: post.link,
			title: this.stripHtml(post.title?.rendered),
			excerpt: this.stripHtml(post.excerpt?.rendered),
			category,
			imageUrl: featuredMedia?.source_url ?? null,
			imageAlt: featuredMedia?.alt_text?.trim() || this.stripHtml(post.title?.rendered)
		};
	}

	private stripHtml(value: string | undefined): string {
		if (!value) {
			return '';
		}

		return value.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
	}
}
